    return out

def ledger(memo):
    body=open(memo).read().split('\n'); claims={}; hdr=None
    for ln in body:
        if not ln.lstrip().startswith('|'): hdr=None; continue
        cs=cells(ln)
        if cs[:3]==['ID','Proposition','Status']: hdr=cs; continue
        if hdr is None: continue
        if all(ch in '-:' for ch in ''.join(cs)) and ''.join(cs): continue
        if len(cs)==len(hdr): claims[cs[0]]=cs[1]
    return claims

def proof(memo,claims):
    recs=[json.loads(l) for l in open(memo+'.evidence.jsonl') if l.strip()]
    fp={}
    for r in recs:
        s=r['subject'][0]; cid=s['name']; d=s['digest']['sha256']; ts=r['predicate']['timestamp']
        if cid not in claims: continue
        cur=hashlib.sha256(claims[cid].encode()).hexdigest()
        if d=='' or d==cur:
            fp[cid]=min(fp.get(cid,ts),ts)
    return fp

def blocks(memo):
