    st={}; hist={}; order=[]
    for e in evs:
        i=e['id']
        if e['event']=='Create':
            st[i]={'heading':e['heading'],'text':e['text'],'cite':list(e.get('cite') or [])}
            b=e.get('before'); order.insert(order.index(b) if b in order else len(order), i)
            hist[i]=[]
        else:
            st[i]['text']=e['text']
            if e.get('cite') is not None: st[i]['cite']=list(e['cite'])
        hist[i].append((e['timestamp'],st[i]['text'],list(st[i]['cite'])))
    return order,st,hist

